#include <LiquidCrystal_I2C.h> // подключаем библиотеку для LCD 1602
#include <dht11.h> // подключаем библиотеку для DHT11
#define DHT11PIN 2 // сигнал DHT11 подключаем к 2-му цифровому выводу

LiquidCrystal_I2C lcd(0x27,16,2); // присваиваем имя lcd для дисплея 16х2

dht11 DHT11;

void setup() // процедура setup
{
  lcd.init(); // инициализация LCD дисплея
  lcd.backlight(); // включение подсветки дисплея
}

void loop() // процедура loop
{
  int chk = DHT11.read(DHT11PIN);

  // Влажность
  lcd.setCursor(0, 0);
  lcd.print("Humidity:");
  lcd.print((float)DHT11.humidity, 2);
  lcd.print(" % ");

  // Температура
  lcd.setCursor(0, 1);
  lcd.print("Temp:    "); 
  lcd.print((float)DHT11.temperature, 2);
  lcd.print(" C ");

  // Частота обновления в мс
  delay(1000);
}
